#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <cctype>
#include <tuple>
#include <algorithm>
using namespace std;

using ll = long long;

const int MAX_SIZE = 7100;
const int MAX_GRID = 14;
const ll INF = 1000000000;

struct Edge {
    int src, dst;
    ll f, c;
};

struct FlowGraph {
    int source, sink;
    vector<Edge> edgeList;
    vector<int> adj[MAX_SIZE];
    int lvl[MAX_SIZE], ptr[MAX_SIZE];

    void reset() {
        edgeList.clear();
        for (int i = 0; i < MAX_SIZE; ++i) adj[i].clear();
    }

    void connect(int u, int v, ll cap) {
        edgeList.push_back({u, v, 0, cap});
        edgeList.push_back({v, u, 0, 0});
        adj[u].push_back(edgeList.size() - 2);
        adj[v].push_back(edgeList.size() - 1);
    }

    bool levelize() {
        memset(lvl, -1, sizeof(lvl));
        queue<int> q;
        q.push(source);
        lvl[source] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int id : adj[u]) {
                Edge& e = edgeList[id];
                if (lvl[e.dst] == -1 && e.c > e.f) {
                    lvl[e.dst] = lvl[u] + 1;
                    q.push(e.dst);
                }
            }
        }
        return lvl[sink] != -1;
    }

    ll augment(int u, ll flow) {
        if (u == sink || flow == 0) return flow;
        for (int& i = ptr[u]; i < (int)adj[u].size(); ++i) {
            int id = adj[u][i];
            Edge& e = edgeList[id];
            if (lvl[e.dst] == lvl[u] + 1 && e.c > e.f) {
                ll pushed = augment(e.dst, min(flow, e.c - e.f));
                if (pushed > 0) {
                    e.f += pushed;
                    edgeList[id ^ 1].f -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    ll compute() {
        ll total = 0;
        while (levelize()) {
            memset(ptr, 0, sizeof(ptr));
            while (ll pushed = augment(source, INF)) {
                total += pushed;
            }
        }
        return total;
    }
};

FlowGraph g;
char map1[MAX_GRID][MAX_GRID], map2[MAX_GRID][MAX_GRID];
bool visited[MAX_GRID][MAX_GRID];
int timeDist[MAX_GRID][MAX_GRID];
int N, T;
int sinkNode[103];

int encode(int t, int x, int y) {
    return t * N * N + (x - 1) * N + y;
}

void computeDist(int sx, int sy) {
    queue<tuple<int, int, int>> q;
    for (int i = 0; i < MAX_GRID; ++i)
        for (int j = 0; j < MAX_GRID; ++j)
            timeDist[i][j] = 111;

    timeDist[sx][sy] = 0;
    q.emplace(sx, sy, 0);
    int dx[] = {1, 0, 0, -1}, dy[] = {0, 1, -1, 0};

    while (!q.empty()) {
        auto [x, y, d] = q.front(); q.pop();
        if (visited[x][y]) continue;
        visited[x][y] = true;
        timeDist[x][y] = d;
        for (int i = 0; i < 4; ++i) {
            int nx = x + dx[i], ny = y + dy[i];
            if (nx < 1 || nx > N || ny < 1 || ny > N || visited[nx][ny] || map1[nx][ny] == 'Y')
                continue;
            q.emplace(nx, ny, d + 1);
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> T;
    for (int i = 1; i <= N; ++i) cin >> (map1[i] + 1);
    for (int i = 1; i <= N; ++i) cin >> (map2[i] + 1);

    g.reset();
    g.source = 0;
    g.sink = MAX_SIZE - 2;

    int startX = 0, startY = 0;
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            if (map1[i][j] == 'Z') {
                startX = i; startY = j;
                break;
            }
        }
    }

    for (int i = 1; i <= N * N; ++i)
        sinkNode[i] = MAX_SIZE - 3 - (N * N - i);

    computeDist(startX, startY);

    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= N; ++j) {
            if (isdigit(map1[i][j]))
                g.connect(g.source, encode(0, i, j), map1[i][j] - '0');
            if (isdigit(map2[i][j]))
                g.connect(sinkNode[encode(0, i, j)], g.sink, map2[i][j] - '0');
            g.connect(encode(0, i, j), sinkNode[encode(0, i, j)], INF);
        }
    }

    int dx[] = {1, 0, 0, -1}, dy[] = {0, 1, -1, 0};
    for (int step = 1; step <= T; ++step) {
        for (int i = 1; i <= N; ++i) {
            for (int j = 1; j <= N; ++j) {
                if (map1[i][j] == 'Y' || map1[i][j] == 'Z') continue;
                for (int d = 0; d < 4; ++d) {
                    int ni = i + dx[d], nj = j + dy[d];
                    if (ni >= 1 && ni <= N && nj >= 1 && nj <= N &&
                        map1[ni][nj] != 'Y' && map1[ni][nj] != 'Z' &&
                        timeDist[i][j] >= step && timeDist[ni][nj] >= step) {
                        g.connect(encode(step - 1, ni, nj), encode(step, i, j), INF);
                    }
                }
                g.connect(encode(step, i, j), sinkNode[encode(0, i, j)], INF);
            }
        }
    }

    cout << g.compute() << '\n';
    return 0;
}
